document.addEventListener('DOMContentLoaded', () => {
  // DOM Elements
  const tapZone = document.getElementById('tap-zone');
  const countDisplay = document.getElementById('count-display');
  const targetDisplay = document.getElementById('target-display');
  const categoryDisplay = document.getElementById('current-category-display');
  
  const categorySelect = document.getElementById('category-type');
  const customCategoryInput = document.getElementById('custom-category');
  
  const targetSelect = document.getElementById('target-type');
  const customTargetInput = document.getElementById('custom-target');
  
  const resetBtn = document.getElementById('reset-btn');
  const decrementBtn = document.getElementById('decrement-btn');
  const toggleSoundBtn = document.getElementById('toggle-sound');
  
  const themeBtn = document.getElementById('theme-btn');
  const soundModalBtn = document.getElementById('sound-modal-btn');
  const volumeSlider = document.getElementById('volume-slider');
  const soundSelectBox = document.getElementById('sound-select');
  
  const circle = document.querySelector('.progress-ring__circle');

  // SVG Math setup
  const radius = circle.r.baseVal.value;
  const circumference = radius * 2 * Math.PI;
  circle.style.strokeDasharray = `${circumference} ${circumference}`;
  circle.style.strokeDashoffset = circumference;

  // New Feature Themes 
  const solidColors = [
    { name: 'Neon Green', c: '#39ff14' }, { name: 'Blue', c: '#007bff' },
    { name: 'Purple', c: '#8a2be2' }, { name: 'Pink', c: '#ff69b4' },
    { name: 'Orange', c: '#ff8c00' }, { name: 'Red', c: '#ff0000' },
    { name: 'Yellow', c: '#ffd700' }, { name: 'Cyan', c: '#00ffff' },
    { name: 'Teal', c: '#008080' }, { name: 'Indigo', c: '#4b0082' },
    { name: 'Lime', c: '#00ff00' }, { name: 'White', c: '#ffffff' },
    { name: 'Gray', c: '#808080' }, { name: 'Dark Blue', c: '#00008b' },
    { name: 'Gold', c: '#d4af37' }, { name: 'Crimson', c: '#dc143c' },
    { name: 'Light Pink', c: '#ffb6c1' }, { name: 'Coral', c: '#ff7f50' },
    { name: 'Tomato', c: '#ff6347' }, { name: 'Violet', c: '#ee82ee' },
    { name: 'Sky Blue', c: '#87ceeb' }, { name: 'Aquamarine', c: '#7fffd4' },
    { name: 'Khaki', c: '#f0e68c' }, { name: 'Silver', c: '#c0c0c0' },
    { name: 'Slate Blue', c: '#6a5acd' }
  ];

  const gradientColors = [
    { name: 'Green → Blue', c1: '#00ff88', c2: '#007bff' },
    { name: 'Purple → Pink', c1: '#8a2be2', c2: '#ff69b4' },
    { name: 'Orange → Red', c1: '#ff8c00', c2: '#ff0000' },
    { name: 'Blue → Cyan', c1: '#007bff', c2: '#00ffff' },
    { name: 'Pink → Violet', c1: '#ff69b4', c2: '#ee82ee' },
    { name: 'Yellow → Orange', c1: '#ffd700', c2: '#ff8c00' },
    { name: 'Teal → Green', c1: '#008080', c2: '#00ff00' },
    { name: 'Indigo → Purple', c1: '#4b0082', c2: '#8a2be2' },
    { name: 'Gold → Orange', c1: '#d4af37', c2: '#ff8c00' },
    { name: 'Rainbow', isRainbow: true }
  ];

  // 25+ Advanced Sound Feature Track List
  const soundLibrary = [
    {
        "name": "Soft Tap",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/button_tiny.mp3"
    },
    {
        "name": "Standard Click",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/button_click.mp3"
    },
    {
        "name": "Deep Push",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/button_push.mp3"
    },
    {
        "name": "Toggle On",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/button_click_on.mp3"
    },
    {
        "name": "Soft Bell",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/bell_ring.mp3"
    },
    {
        "name": "Snap",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/snap.mp3"
    },
    {
        "name": "Light Pop",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/pop_cork.mp3"
    },
    {
        "name": "UI Tick",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/tap.mp3"
    },
    {
        "name": "Water Drop 1",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/water_droplet.mp3"
    },
    {
        "name": "Water Drop 2",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/water_droplet_2.mp3"
    },
    {
        "name": "Digital Beep",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/computer_error.mp3"
    },
    {
        "name": "Door Bell",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/door_bell.mp3"
    },
    {
        "name": "Glass Ping",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/glass.mp3"
    },
    {
        "name": "Keyboard Click",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/keyboard_desk.mp3"
    },
    {
        "name": "Metal Plate",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/metal_plate.mp3"
    },
    {
        "name": "Sharp Metal",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/metal_plate_2.mp3"
    },
    {
        "name": "Branch Break",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/branch_break.mp3"
    },
    {
        "name": "Staple Click",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/staple_gun.mp3"
    },
    {
        "name": "Camera Flash",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/camera_flashing.mp3"
    },
    {
        "name": "Light Bulb Break",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/light_bulb_breaking.mp3"
    },
    {
        "name": "Beer Can",
        "url": "https://raw.githubusercontent.com/IonDen/ion.sound/master/sounds/beer_can_opening.mp3"
    },
    {
        "name": "Sci-Fi Click",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Deep Pop",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Tiny Tick",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Space Beep",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Low Thump",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "High Chime",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Static Tap",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Digital Coin",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Subtle Dot",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Hollow Tap",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Harsh Click",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Muted Blip",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Laser Drop",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Warm Pluck",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Retro Jump",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Glass Ping",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Soft Thud",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Mechanical Switch",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Clean Pop",
        "url": "data:audio/wav;base64,"
    },
    {
        "name": "Tiny Zap",
        "url": "data:audio/wav;base64,"
    }
];

  // Global Audio Preload Caching Structure
  let currentAudioURL = soundLibrary[0].url;

  // State Management
  let state = JSON.parse(localStorage.getItem('clickTrackerStateUltra')) || {
    count: 0,
    category: 'Workout Reps',
    customCategory: '',
    target: 10,
    customTarget: 100,
    soundEnabled: true,
    volume: 1.0,
    soundIndex: 0,
    theme: { type: 'solid', index: 7, isDefault: true } 
  };

  // Logic
  init();

  function hexToRgba(hex, alpha) {
    var r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  }

  function applyTheme() {
    const root = document.documentElement;
    let selectedTheme;

    if (state.theme.isDefault) {
      root.style.setProperty('--accent-primary', '#00e5ff');
      root.style.setProperty('--accent-secondary', '#00e5ff');
      root.style.setProperty('--accent-glow', 'rgba(0, 229, 255, 0.4)');
      circle.style.stroke = 'url(#ringGradient)';
    } else if (state.theme.type === 'solid') {
      selectedTheme = solidColors[state.theme.index];
      root.style.setProperty('--accent-primary', selectedTheme.c);
      root.style.setProperty('--accent-secondary', selectedTheme.c);
      root.style.setProperty('--accent-glow', hexToRgba(selectedTheme.c, 0.4));
      circle.style.stroke = 'url(#ringGradient)';
    } else if (state.theme.type === 'gradient') {
      selectedTheme = gradientColors[state.theme.index];
      if (selectedTheme.isRainbow) {
        root.style.setProperty('--accent-primary', '#ff0000');
        root.style.setProperty('--accent-secondary', '#4b0082');
        root.style.setProperty('--accent-glow', 'rgba(255, 0, 0, 0.4)');
        circle.style.stroke = 'url(#ringGradientRainbow)';
      } else {
        root.style.setProperty('--accent-primary', selectedTheme.c1);
        root.style.setProperty('--accent-secondary', selectedTheme.c2);
        root.style.setProperty('--accent-glow', hexToRgba(selectedTheme.c1, 0.4));
        circle.style.stroke = 'url(#ringGradient)';
      }
    }
  }

  function renderThemeModal() {
    const solidContainer = document.getElementById('solid-themes-grid');
    const gradientContainer = document.getElementById('gradient-themes-grid');
    
    solidColors.forEach((color, index) => {
      const bubble = document.createElement('div');
      bubble.className = 'theme-bubble';
      bubble.style.background = color.c;
      bubble.title = color.name;
      bubble.onclick = () => { selectTheme('solid', index); };
      solidContainer.appendChild(bubble);
    });

    gradientColors.forEach((grad, index) => {
      const bubble = document.createElement('div');
      bubble.className = 'theme-bubble';
      if (grad.isRainbow) {
        bubble.style.background = 'linear-gradient(45deg, red, orange, yellow, green, blue, indigo)';
      } else {
        bubble.style.background = `linear-gradient(45deg, ${grad.c1}, ${grad.c2})`;
      }
      bubble.title = grad.name;
      bubble.onclick = () => { selectTheme('gradient', index); };
      gradientContainer.appendChild(bubble);
    });
  }

  function renderSoundSelector() {
     soundLibrary.forEach((sound, index) => {
        let option = document.createElement('option');
        option.value = index;
        option.textContent = `${index + 1}. ${sound.name}`;
        soundSelectBox.appendChild(option);
     });
     
     soundSelectBox.value = state.soundIndex;
     currentAudioURL = soundLibrary[state.soundIndex].url;
     volumeSlider.value = state.volume;
     
     updateSoundToggleState();
  }

  function selectTheme(type, index) {
    state.theme = { type, index, isDefault: false };
    applyTheme();
    saveState();
  }

  function init() {
    applyTheme();
    renderThemeModal();
    renderSoundSelector();

    if (['Workout Reps', 'Steps Count', 'Habit Tracker'].includes(state.category)) {
      categorySelect.value = state.category;
    } else {
      categorySelect.value = 'Custom';
      customCategoryInput.style.display = 'block';
      customCategoryInput.value = state.category;
    }

    if ([10, 50, 100, 'Infinity'].includes(state.target)) {
      targetSelect.value = state.target;
    } else {
      targetSelect.value = 'Custom';
      customTargetInput.style.display = 'block';
      customTargetInput.value = state.target;
    }

    updateUI();
  }

  function saveState() {
    localStorage.setItem('clickTrackerStateUltra', JSON.stringify(state));
  }

  function updateUI() {
    countDisplay.textContent = state.count;
    categoryDisplay.textContent = state.category;
    
    if (state.target === 'Infinity') {
      targetDisplay.textContent = '';
      setProgress(0); 
    } else {
      targetDisplay.textContent = `/ ${state.target}`;
      const progress = Math.min((state.count / state.target) * 100, 100);
      setProgress(progress);
    }
  }

  function setProgress(percent) {
    const offset = circumference - (percent / 100) * circumference;
    circle.style.strokeDashoffset = offset;
  }

  function increment(e) {
    const targetValue = state.target === 'Infinity' ? Infinity : parseInt(state.target);
    
    if (state.count >= targetValue && targetValue !== Infinity) {
      if (navigator.vibrate) navigator.vibrate(300); 
      return; 
    }

    state.count++;
    saveState();
    updateUI();
    triggerFeedback(targetValue);
    
    if (e) createRipple(e);
  }

  function decrement() {
    if (state.count > 0) {
      state.count--;
      saveState();
      updateUI();
      if (navigator.vibrate) navigator.vibrate(20);
    }
  }

  // Audio System
  let globalAudioPlayer = new Audio();
  globalAudioPlayer.preload = 'auto';

  function triggerFeedback(targetValue) {
    if (state.soundEnabled) {
      if (globalAudioPlayer.src !== currentAudioURL) {
         globalAudioPlayer.src = currentAudioURL;
         globalAudioPlayer.load();
      }
      globalAudioPlayer.volume = state.volume;
      globalAudioPlayer.currentTime = 0;
      
      const playPromise = globalAudioPlayer.play();
      if (playPromise !== undefined) {
         playPromise.catch(error => {
            // Fallback: If selected sound URL failed or 404s, fallback to a guaranteed base64 or stable URL.
            console.warn("Sound failed, switching to fallback.", error);
            globalAudioPlayer.src = soundLibrary[1].url; // Usually 'Standard Click'
            globalAudioPlayer.currentTime = 0;
            globalAudioPlayer.play().catch(() => {});
         });
      }
    }
    if (navigator.vibrate) {
      state.count === targetValue ? navigator.vibrate([100, 50, 100, 50, 200]) : navigator.vibrate(20); 
    }
  }

  function createRipple(e) {
    if (e.clientX === 0 && e.clientY === 0) return; 
    const rect = tapZone.getBoundingClientRect();
    const x = e.clientX ? e.clientX - rect.left : rect.width / 2;
    const y = e.clientY ? e.clientY - rect.top : rect.height / 2;
    
    const ripple = document.createElement('span');
    ripple.classList.add('ripple');
    ripple.style.left = `${x}px`;
    ripple.style.top = `${y}px`;
    ripple.style.width = ripple.style.height = '100px';
    ripple.style.marginLeft = ripple.style.marginTop = '-50px';
    
    tapZone.appendChild(ripple);
    setTimeout(() => ripple.remove(), 500); 
  }

  // Interaction Events
  tapZone.addEventListener('pointerdown', increment);
  decrementBtn.addEventListener('click', decrement);

  resetBtn.addEventListener('click', () => {
    state.count = 0;
    saveState();
    updateUI();
    if (navigator.vibrate) navigator.vibrate(50);
  });

  categorySelect.addEventListener('change', (e) => {
    if (e.target.value === 'Custom') {
      customCategoryInput.style.display = 'block';
      state.category = customCategoryInput.value || 'Custom Item';
    } else {
      customCategoryInput.style.display = 'none';
      state.category = e.target.value;
    }
    saveState();
    updateUI();
  });

  customCategoryInput.addEventListener('input', (e) => {
    state.category = e.target.value || 'Custom Item';
    saveState();
    updateUI();
  });

  targetSelect.addEventListener('change', (e) => {
    if (e.target.value === 'Custom') {
      customTargetInput.style.display = 'block';
      state.target = parseInt(customTargetInput.value) || 100;
    } else if (e.target.value === 'Infinity') {
      customTargetInput.style.display = 'none';
      state.target = 'Infinity';
    } else {
      customTargetInput.style.display = 'none';
      state.target = parseInt(e.target.value);
    }
    saveState();
    updateUI();
  });

  customTargetInput.addEventListener('input', (e) => {
    const val = parseInt(e.target.value);
    if (val > 0) {
      state.target = val;
      saveState();
      updateUI();
    }
  });

  // Sound Feature Controllers
  function updateSoundToggleState() {
     if (state.soundEnabled) {
       toggleSoundBtn.classList.add('active');
       toggleSoundBtn.classList.remove('action-btn');
       toggleSoundBtn.textContent = '🔊 Sound Active';
       document.getElementById('sound-modal-btn').style.opacity = '1';
     } else {
       toggleSoundBtn.classList.remove('active');
       toggleSoundBtn.classList.add('action-btn');
       toggleSoundBtn.textContent = '🔇 Muted';
       document.getElementById('sound-modal-btn').style.opacity = '0.5';
     }
  }

  toggleSoundBtn.addEventListener('click', () => {
    state.soundEnabled = !state.soundEnabled;
    saveState();
    updateSoundToggleState();
    if (state.soundEnabled) {
       // test play
       const clickInstance = new Audio(currentAudioURL);
       clickInstance.volume = state.volume;
       clickInstance.play().catch(() => {});
    }
  });

  volumeSlider.addEventListener('input', (e) => {
     state.volume = parseFloat(e.target.value);
     saveState();
  });

  soundSelectBox.addEventListener('change', (e) => {
     state.soundIndex = parseInt(e.target.value);
     currentAudioURL = soundLibrary[state.soundIndex].url;
     saveState();
     // Test play immediately on selection changed
     if (state.soundEnabled) {
       const clickInstance = new Audio(currentAudioURL);
       clickInstance.volume = state.volume;
       clickInstance.play().catch(() => {});
     }
  });

  // Modals Framework
  const themeModal = document.getElementById('theme-modal');
  themeBtn.addEventListener('click', () => themeModal.classList.remove('hidden'));
  document.getElementById('close-theme-btn').addEventListener('click', () => themeModal.classList.add('hidden'));
  themeModal.addEventListener('click', (e) => { if (e.target === themeModal) themeModal.classList.add('hidden'); });
  
  document.getElementById('default-theme-btn').addEventListener('click', () => {
    state.theme.isDefault = true;
    applyTheme();
    saveState();
  });

  const soundModal = document.getElementById('sound-modal');
  soundModalBtn.addEventListener('click', () => soundModal.classList.remove('hidden'));
  document.getElementById('close-sound-btn').addEventListener('click', () => soundModal.classList.add('hidden'));
  soundModal.addEventListener('click', (e) => { if (e.target === soundModal) soundModal.classList.add('hidden'); });

});
